-- For existing teams, set departmentId to 1 (or create a default department)
-- First, ensure there's at least one department
INSERT IGNORE INTO departments (id, divisionId, code, name, description, createdBy, updatedBy)
VALUES (1, 1, 'DEPT-DEFAULT', 'Default Department', 'Default department for migration', 1, 1);

-- Update existing teams to use departmentId instead of groupId
UPDATE teams SET departmentId = 1 WHERE departmentId = 0;

-- Drop the old groupId column
ALTER TABLE teams DROP COLUMN IF EXISTS groupId;

